mapper.select:
SELECT CONTRACT.CONTRACT_ID, CONTRACT.CONTRACT_NAME, CONTRACT.CONTRACT_NUMBER, CONTRACT.CON_DOCUMENT_CATEGORY, CONTRACT.TIMES, MAX(CONTRACT.DUE_DATE) DUE_DATE, SUM(CONTRACT.DUE_AMOUNT) DUE_AMOUNT, SUM(nvl(CONTRACT.RECEIVED_AMOUNT,0)) RECEIVED_AMOUNT, SUM(nvl(CONTRACT.DUE_AMOUNT,0) -nvl(CONTRACT.RECEIVED_AMOUNT,0)) SURPLUS_AMOUNT, SUM(CONTRACT.PRINCIPAL) PRINCIPAL, SUM(CONTRACT.INTEREST) INTEREST FROM ( ( SELECT CON.CONTRACT_ID, CON.CONTRACT_NAME, CON.CONTRACT_NUMBER, CON.COMPANY_ID, CON_FLOW.CASHFLOW_ID, CON_FLOW.DUE_DATE, CON_FLOW.DUE_AMOUNT, CON_FLOW.RECEIVED_AMOUNT, CON_FLOW.TIMES, CON_FLOW.WRITE_OFF_FLAG, CON_FLOW.CF_ITEM, CON_FLOW.CF_TYPE, nvl(CON_FLOW.PRINCIPAL,0) PRINCIPAL, nvl(CON_FLOW.INTEREST,0) INTEREST, 'CON_CONTRACT' CON_DOCUMENT_CATEGORY FROM CON_CONTRACT CON JOIN CON_CONTRACT_CASHFLOW CON_FLOW ON CON.CONTRACT_ID=CON_FLOW.CONTRACT_ID WHERE CON.DATA_CLASS='NORMAL' AND CON_FLOW.CF_STATUS='RELEASE' AND CON_FLOW.CF_DIRECTION='INFLOW' AND CON_FLOW.CF_ITEM =1 ) UNION ( SELECT CON.CONTRACT_ID, CON.CONTRACT_NAME, CON.CONTRACT_NUMBER, CON.COMPANY_ID, CON_FLOW.QUOTATION_CASHFLOW_ID CASHFLOW_ID, CON_FLOW.DUE_DATE, CON_FLOW.DUE_AMOUNT, CON_FLOW.RECEIVED_AMOUNT, CON_FLOW.TIMES, CON_FLOW.WRITE_OFF_FLAG, CON_FLOW.CF_ITEM, CON_FLOW.CF_TYPE, CASE WHEN CON_FLOW.CF_ITEM=54 THEN nvl(CON_FLOW.DUE_AMOUNT,0) ELSE 0 END PRINCIPAL, CASE WHEN CON_FLOW.CF_ITEM=55 THEN nvl(CON_FLOW.DUE_AMOUNT,0) ELSE 0 END INTEREST, 'FCT_CONTRACT' CON_DOCUMENT_CATEGORY FROM FCT_CONTRACT CON JOIN FCT_QUOTATION_CASHFLOW CON_FLOW ON CON.CONTRACT_ID=CON_FLOW.CONTRACT_ID WHERE CON.DATA_CLASS='NORMAL' AND CON_FLOW.CF_STATUS='RELEASE' AND CON_FLOW.CF_DIRECTION='INFLOW' AND CON_FLOW.CF_ITEM IN(54,55) ) ) CONTRACT WHERE 1=1
AND CONTRACT.CONTRACT_ID=#{contractId}
AND CONTRACT.DUE_DATE>= (SELECT CP.BASE_DATE FROM CT_ABS_ASSETS_PACK CP WHERE CP.PACK_ID=#{packId})
AND CONTRACT.CON_DOCUMENT_CATEGORY=#{conDocumentCategory}
AND CONTRACT.TIMES=#{times}
AND CONTRACT.TIMES >= #{timesFrom}
AND CONTRACT.TIMES <= #{timesTo}
GROUP BY CONTRACT.CONTRACT_ID, CONTRACT.CONTRACT_NAME, CONTRACT.CONTRACT_NUMBER, CONTRACT.CON_DOCUMENT_CATEGORY, CONTRACT.TIMES ORDER BY CONTRACT.TIMES

SELECT CON.CONTRACT_ID, CON.CON_DOCUMENT_CATEGORY, nvl(SUM(CASE WHEN CON.OVERDUE_STATUS='Y' THEN 1 ELSE 0 END),0) OVERDUE_STATUS, nvl(SUM(CON.UNCOLLECTED_DUE_AMOUNT),0) UNCOLLECTED_DUE_AMOUNT, nvl(SUM(CON.UNCOLLECTED_PRINCIPAL),0) UNCOLLECTED_PRINCIPAL, nvl(SUM(CON.UNCOLLECTED_INTEREST),0) UNCOLLECTED_INTEREST FROM ( SELECT FC.CONTRACT_ID, 'FCT_CONTRACT' CON_DOCUMENT_CATEGORY, CA.QUOTATION_CASHFLOW_ID CASHFLOW_ID, CA.CF_ITEM, CA.TIMES, CA.OVERDUE_STATUS, nvl(CA.DUE_AMOUNT,0)-nvl(CA.RECEIVED_AMOUNT,0) UNCOLLECTED_DUE_AMOUNT, CASE WHEN CA.CF_ITEM=54 THEN nvl(CA.DUE_AMOUNT,0)-nvl(CA.RECEIVED_AMOUNT,0) ELSE 0 END UNCOLLECTED_PRINCIPAL, CASE WHEN CA.CF_ITEM=55 THEN nvl(CA.DUE_AMOUNT,0)-nvl(CA.RECEIVED_AMOUNT,0) ELSE 0 END UNCOLLECTED_INTEREST FROM FCT_CONTRACT FC JOIN FCT_QUOTATION_CASHFLOW CA ON FC.CONTRACT_ID=CA.CONTRACT_ID WHERE FC.DATA_CLASS='NORMAL' AND CA.CF_STATUS = 'RELEASE' AND CA.CF_DIRECTION = 'INFLOW' AND CA.CF_ITEM IN(54,55) UNION SELECT FC.CONTRACT_ID, 'CON_CONTRACT' CON_DOCUMENT_CATEGORY, CA.CASHFLOW_ID, CA.CF_ITEM, CA.TIMES, CA.OVERDUE_STATUS, nvl(CA.DUE_AMOUNT,0)-nvl(CA.RECEIVED_AMOUNT,0) UNCOLLECTED_DUE_AMOUNT, nvl(CA.PRINCIPAL,0)-nvl(CA.RECEIVED_PRINCIPAL,0) UNCOLLECTED_PRINCIPAL, nvl(CA.INTEREST,0)-nvl(CA.RECEIVED_INTEREST,0) UNCOLLECTED_INTEREST FROM CON_CONTRACT FC JOIN CON_CONTRACT_CASHFLOW CA ON FC.CONTRACT_ID=CA.CONTRACT_ID WHERE FC.DATA_CLASS='NORMAL' AND CA.CF_STATUS = 'RELEASE' AND CA.CF_DIRECTION = 'INFLOW' AND CA.CF_ITEM =1 ) CON WHERE 1=1
AND CON.CONTRACT_ID=#{contractId}
AND CON.CON_DOCUMENT_CATEGORY=#{conDocumentCategory}
AND CON.TIMES >= #{timesFrom}
AND CON.TIMES <= #{timesTo}
GROUP BY CON.CONTRACT_ID, CON.CON_DOCUMENT_CATEGORY

SELECT count( 0 ) FROM ( SELECT ccc.* FROM con_contract_cashflow ccc, ct_abs_assets_package caap WHERE ccc.CONTRACT_ID = caap.CONTRACT_ID AND ccc.DUE_DATE >= caap.PACK_DATE_FROM AND ccc.DUE_DATE <= caap.PACK_DATE_TO AND ccc.CONTRACT_ID = #{contractId}
AND caap.package_id != #{packageId}
UNION SELECT ccc.* FROM con_contract_cashflow ccc, ct_lon_contract_pledge clcp WHERE ccc.CONTRACT_ID = clcp.pledge_doc_id AND ccc.DUE_DATE >= clcp.PLEDGE_TIMES_FROM AND ccc.DUE_DATE <= clcp.PLEDGE_TIMES_TO AND ccc.CONTRACT_ID = #{contractId} ) v WHERE v.DUE_DATE >= #{packDateFrom} AND v.DUE_DATE <= #{packDateTo}
